class Solution {public:bool solve(int n,vector<vector<int>>edges){vector<vector<int>>a(n);for(auto e:edges){a[e[0]].push_back(e[1]);a[e[1]].push_back(e[0]);}vector<int>color(n,-1);for(int s=0;s<n;s++)if(color[s]<0){queue<int>q;q.push(s);color[s]=0;while(!q.empty()){int u=q.front();q.pop();for(int v:a[u])if(color[v]<0){color[v]=color[u]^1;q.push(v);}else if(color[v]==color[u])return false;}}return true;}};